<script setup lang="ts">
import { ref } from "vue";
import { http } from "@/utils/http";
const tab = ref("policy"); const challenges = ref<any[]>([]); const loading = ref(false); const error = ref("");
async function load() { loading.value = true; try { const result = await http.get<unknown, unknown>("/security/verification-challenges"); challenges.value = Array.isArray(result) ? result as any[] : []; } catch (e: any) { error.value = e?.response?.data?.detail || "认证策略接口尚未接入"; } finally { loading.value = false; } }
load();
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">认证、密钥与恢复</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">查看认证策略和安全材料状态；Secret Material 永不在此明文显示。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="warning" show-icon :closable="false" class="mb-4"/><el-tabs v-model="tab"><el-tab-pane label="认证策略" name="policy"/><el-tab-pane label="密钥与 Secret" name="secrets"/><el-tab-pane label="恢复" name="recovery"/><el-tab-pane label="OAuth/API 访问" name="oauth"/></el-tabs><el-card shadow="never" class="mt-4"><template v-if="tab === 'policy'"><div class="grid grid-cols-1 md:grid-cols-2 gap-4"><el-card v-for="item in [{name:'Password / Login Policy',value:'由服务端生效',hint:'登录密码校验与失败策略'},{name:'MFA 要求',value:'由安全策略提供',hint:'高风险操作可能要求二次验证'},{name:'JWT Lifetime',value:'由认证服务提供',hint:'Access Token 过期后使用 Refresh Token'},{name:'Login Rate Limit',value:'由认证服务提供',hint:'失败次数和锁定策略'}]" :key="item.name" shadow="never"><div class="font-medium">{{ item.name }}</div><div class="text-lg mt-3">{{ item.value }}</div><div class="text-sm text-[var(--el-text-color-secondary)] mt-2">{{ item.hint }}</div></el-card></div><el-alert title="策略修改必须经过 Diff Review，并产生 Audit Event。当前页面不直接保存策略。" type="info" show-icon class="mt-5"/></template><template v-else-if="tab === 'secrets'"><el-empty description="暂无可展示的密钥目录；仅展示 Active / Retiring / Revoked 状态，不展示 Secret Material"/></template><template v-else-if="tab === 'recovery'"><el-empty description="Recovery Readiness 由受保护域后端提供，不展示 Recovery Material"/><el-button>验证恢复能力</el-button></template><template v-else><el-empty v-if="!challenges.length" description="暂无 OAuth/API Client；Token Secret 只展示一次"/><el-table v-else :data="challenges" stripe><el-table-column prop="id" label="Client / Challenge" min-width="240"/><el-table-column prop="method" label="方法" width="150"/><el-table-column prop="status" label="状态" width="120"/><el-table-column prop="expiresAt" label="过期时间" min-width="180"/></el-table></template></el-card></main></template>
